37	
38	/**
39	 * 批次隔离与放行核心服务。
40	 *
41	 * <p>并发策略：同一批次的检验/批准/召回在事务内对 batch 行 SELECT ... FOR UPDATE 串行化，
42	 * 按事务提交顺序生效；commandKey 幂等通过 command_log 主键 + 参数指纹实现，
43	 * 同键同参重放返回首次响应快照，同键改参返回 409；仅成功命令写入 command_log。
44	 */
45	@Service
46	public class BatchService {
47	
48	    private static final String CMD_CREATE = "CREATE_BATCH";
49	    private static final String CMD_TEST = "SUBMIT_TEST";
50	    private static final String CMD_APPROVE = "APPROVE";
51	    private static final String CMD_RECALL = "RECALL";
52	    private static final String CMD_SPLIT = "SPLIT";
53	
54	    /**
55	     * 指纹拼接分隔符（NUL）：业务参数不可能包含该字符，避免拼接碰撞。
56	     */
57	    private static final String SEP = "\u0000";
58	
59	    private static final int IDEMPOTENCY_MAX_ATTEMPTS = 3;
60	
61	    private final BatchRepository repo;
62	    private final TransactionTemplate tx;
63	    private final ObjectMapper objectMapper;
64	
65	    public BatchService(BatchRepository repo,
66	                        PlatformTransactionManager transactionManager,
67	                        ObjectMapper objectMapper) {
68	        this.repo = repo;
69	        this.tx = new TransactionTemplate(transactionManager);
70	        this.objectMapper = objectMapper;
71	    }
72	
73	    /**
74	     * 创建批次：初始状态 QUARANTINED；batchKey 全局唯一，重复返回 409。
75	     */
76	    public StoredResponse createBatch(CreateBatchRequest req) {
77	        List<String> items = req.requiredTests().stream().map(String::trim).toList();
78	        if (new HashSet<>(items).size() != items.size()) {
79	            throw ApiException.badRequest("requiredTests 存在重复检验项");
80	        }
81	        String fingerprint = fingerprint("create", req.batchKey(), req.productCode(), req.batchNo(),
82	                req.producedAt().toString(), String.join(SEP, items));
83	        return executeIdempotent(CMD_CREATE, req.commandKey(), fingerprint, () -> {
84	            repo.findBatch(req.batchKey()).ifPresent(b -> {
85	                throw ApiException.conflict("batchKey 已存在: " + req.batchKey());
86	            });
87	            String now = now();
88	            repo.insertBatch(new BatchRepository.BatchRow(0L, req.batchKey(), req.productCode(),
89	                    req.batchNo(), req.producedAt().toString(), BatchStatus.QUARANTINED.name(), now));
90	            for (int i = 0; i < items.size(); i++) {
91	                repo.insertRequiredTest(req.batchKey(), items.get(i), i + 1);
92	            }
93	            BatchResponse body = new BatchResponse(req.batchKey(), req.productCode(), req.batchNo(),
94	                    req.producedAt(), BatchStatus.QUARANTINED, items, Instant.parse(now));
95	            return new StoredResponse(201, toJson(body));
96	        });
