158	    /**
159	     * 批准：两步放行。首个有效批准进入 RELEASE_REVIEW，第二个不同角色、不同批准人批准后 RELEASED。
160	     */
161	    public StoredResponse approve(String batchKey, String actorId, String roleHeader, ApproveRequest req) {
162	        if (actorId == null || actorId.isBlank()) {
163	            throw ApiException.badRequest("X-Actor-Id 不能为空");
164	        }
165	        ApprovalRole role = parseRole(roleHeader);
166	        String actor = actorId.trim();
167	        String fingerprint = fingerprint("approve", batchKey, actor, role.name());
168	        return executeIdempotent(CMD_APPROVE, req.commandKey(), fingerprint, () -> {
169	            BatchRepository.BatchRow batch = repo.findBatchForUpdate(batchKey)
170	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
171	            BatchStatus status = BatchStatus.valueOf(batch.status());
172	            assertNoRecalledAncestor(batchKey);
173	            if (status == BatchStatus.QUARANTINED) {
174	                throw ApiException.unprocessable("必做检验项未全部通过，不能批准");
175	            }
176	            if (status != BatchStatus.PENDING_RELEASE && status != BatchStatus.RELEASE_REVIEW) {
177	                throw ApiException.conflict("批次状态 " + status + " 不允许批准");
178	            }
179	            boolean actorInspected = repo.findTests(batchKey).stream()
180	                    .anyMatch(t -> t.inspector().equals(actor));
181	            if (actorInspected) {
182	                throw ApiException.unprocessable("批准人不得为该批次任一检验结果的检验人: " + actor);
183	            }
184	
185	            List<BatchRepository.ApprovalRow> approvals = repo.findApprovals(batchKey);
186	            String now = now();
187	            int seq;
188	            BatchStatus newStatus;
189	            if (approvals.isEmpty()) {
190	                seq = 1;
191	                newStatus = BatchStatus.RELEASE_REVIEW;
192	            } else {
193	                BatchRepository.ApprovalRow first = approvals.get(0);
194	                if (first.role().equals(role.name())) {
195	                    throw ApiException.conflict("角色 " + role + " 已批准过，需要另一种角色");
196	                }
197	                if (first.actorId().equals(actor)) {
198	                    throw ApiException.conflict("两个批准人必须不同: " + actor);
199	                }
200	                seq = 2;
201	                newStatus = BatchStatus.RELEASED;
202	            }
203	            repo.insertApproval(new BatchRepository.ApprovalRow(0L, batchKey, req.commandKey(),
204	                    actor, role.name(), seq, now));
205	            repo.updateStatus(batchKey, newStatus.name());
206	            ApprovalResponse body = new ApprovalResponse(batchKey, actor, role, seq, newStatus,
207	                    Instant.parse(now));
208	            return new StoredResponse(201, toJson(body));
209	        });
210	    }
