261	    /**
262	     * 批次完整历史：批次概要 + 全部检验 + 全部批准 + 召回记录，历史不因召回而删除或改写。
263	     */
264	    public BatchHistoryResponse history(String batchKey) {
265	        BatchRepository.BatchRow batch = repo.findBatch(batchKey)
266	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
267	        List<String> required = repo.findRequiredTests(batchKey);
268	        List<BatchRepository.TestRow> testRows = repo.findTests(batchKey);
269	        // 按提交顺序推导每条检验结果落定后的批次状态快照：FAIL→REJECTED；
270	        // 必做项全部 PASS 时该条→PENDING_RELEASE；其余→QUARANTINED。
271	        List<TestResultResponse> tests = new java.util.ArrayList<>(testRows.size());
272	        for (BatchRepository.TestRow t : testRows) {
273	            tests.add(toTestResponse(t, snapshotAfter(t, testRows, required).name()));
274	        }
275	        List<ApprovalResponse> approvals = repo.findApprovals(batchKey).stream()
276	                .map(a -> {
277	                    // 历史快照：第一笔批准落定 RELEASE_REVIEW，第二笔落定 RELEASED；不随后续召回改写
278	                    BatchStatus snapshot = a.seq() == 1
279	                            ? BatchStatus.RELEASE_REVIEW
280	                            : BatchStatus.RELEASED;
281	                    return new ApprovalResponse(a.batchKey(), a.actorId(), ApprovalRole.valueOf(a.role()),
282	                            a.seq(), snapshot, Instant.parse(a.createdAt()));
283	                })
284	                .toList();
285	        RecallResponse recall = repo.findRecall(batchKey)
286	                .map(r -> new RecallResponse(r.batchKey(), r.actorId(), r.reason(),
287	                        BatchStatus.RECALLED, Instant.parse(r.createdAt())))
288	                .orElse(null);
289	        return new BatchHistoryResponse(toBatchResponse(batch), tests, approvals, recall);
290	    }
