349	    private TestResultResponse toTestResponse(BatchRepository.TestRow row, String batchStatus) {
350	        return new TestResultResponse(row.batchKey(), row.testKey(), row.testItem(),
351	                TestOutcome.valueOf(row.outcome()), row.inspector(),
352	                BatchStatus.valueOf(batchStatus), Instant.parse(row.createdAt()));
