379	    private ApprovalRole parseRole(String roleHeader) {
380	        if (roleHeader == null || roleHeader.isBlank()) {
381	            throw ApiException.badRequest("X-Approval-Role 不能为空");
382	        }
383	        try {
384	            return ApprovalRole.valueOf(roleHeader.trim());
385	        } catch (IllegalArgumentException e) {
386	            throw ApiException.badRequest("X-Approval-Role 必须为 QUALITY 或 OPERATIONS");
387	        }
388	    }
