417	    /**
418	     * 拆分：仅当前可用的 RELEASED 批次可一次拆成 2～5 个全新子批。
419	     * 子批继承产品编码、生产 UTC 时间与必做检验项，初始 QUARANTINED，
420	     * 不继承检验或批准记录；父批置为 SPLIT 不再可用。
421	     * 创建全部子批、血缘关系与父批状态在同一事务提交；任一子批键已存在或重复，整次 409 且父批不变。
422	     */
423	    public StoredResponse split(String parentKey, SplitRequest req) {
424	        List<SplitRequest.ChildSpec> children = req.children();
425	        List<String> childKeys = children.stream().map(SplitRequest.ChildSpec::batchKey).toList();
426	        if (new HashSet<>(childKeys).size() != childKeys.size()) {
427	            throw ApiException.conflict("子批 batchKey 在请求内重复");
428	        }
429	        List<String> parts = new ArrayList<>();
430	        parts.add("split");
431	        parts.add(parentKey);
432	        for (SplitRequest.ChildSpec child : children) {
433	            parts.add(child.batchKey());
434	            parts.add(child.batchNo());
435	        }
436	        String fingerprint = fingerprint(parts.toArray(new String[0]));
437	        return executeIdempotent(CMD_SPLIT, req.commandKey(), fingerprint, () -> {
438	            BatchRepository.BatchRow parent = repo.findBatchForUpdate(parentKey)
439	                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + parentKey));
440	            // 父批行锁后重查命令快照：并发同键请求在锁等待期间可能已由对方提交，
441	            // 此时须重放首次结果而不是因父批已 SPLIT 误判冲突
442	            var logged = loggedResponse(CMD_SPLIT, req.commandKey(), fingerprint);
443	            if (logged.isPresent()) {
444	                return logged.get();
445	            }
446	            assertNoRecalledAncestor(parentKey);
447	            if (!BatchStatus.RELEASED.name().equals(parent.status())) {
448	                throw ApiException.conflict(
449	                        "批次状态 " + parent.status() + " 不允许拆分，仅当前可用的 RELEASED 批次可拆分");
450	            }
451	            for (String childKey : childKeys) {
452	                if (repo.findBatch(childKey).isPresent()) {
453	                    throw ApiException.conflict("子批 batchKey 已存在: " + childKey);
454	                }
455	            }
456	            String now = now();
457	            List<String> required = repo.findRequiredTests(parentKey);
458	            List<SplitResponse.SplitChild> childBodies = new ArrayList<>(children.size());
459	            for (int i = 0; i < children.size(); i++) {
460	                SplitRequest.ChildSpec spec = children.get(i);
461	                repo.insertBatch(new BatchRepository.BatchRow(0L, spec.batchKey(), parent.productCode(),
462	                        spec.batchNo(), parent.producedAt(), BatchStatus.QUARANTINED.name(), now));
463	                for (int j = 0; j < required.size(); j++) {
464	                    repo.insertRequiredTest(spec.batchKey(), required.get(j), j + 1);
465	                }
466	                repo.insertLineage(new BatchRepository.LineageRow(0L, parentKey, spec.batchKey(),
467	                        i + 1, now));
468	                childBodies.add(new SplitResponse.SplitChild(spec.batchKey(), spec.batchNo(),
469	                        parent.productCode(), Instant.parse(parent.producedAt()),
470	                        BatchStatus.QUARANTINED, required, Instant.parse(now)));
471	            }
472	            repo.updateStatus(parentKey, BatchStatus.SPLIT.name());
473	            SplitResponse body = new SplitResponse(parentKey, BatchStatus.SPLIT, childBodies,
474	                    Instant.parse(now));
475	            return new StoredResponse(201, toJson(body));
476	        });
477	    }
