523	    /**
524	     * 沿父链向上查找最近的被直接召回（RECALLED）祖先；批次自身召回不算祖先召回。
525	     */
526	    private Optional<String> recalledAncestor(String batchKey, Map<String, String> parentOf,
527	                                              Set<String> recalled) {
528	        String current = batchKey;
529	        while (parentOf.containsKey(current)) {
530	            current = parentOf.get(current);
531	            if (recalled.contains(current)) {
532	                return Optional.of(current);
533	            }
534	        }
535	        return Optional.empty();
