354	    void concurrentSameActorTwoRoles_cannotRelease() throws Exception {
355	        String batchKey = "BK-RACE-ACTOR-" + unique();
356	        createBatch(batchKey, List.of("t1"), 201);
357	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp"), null, null, 201);
358	
359	        List<Future<Integer>> results = runConcurrent(
360	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
361	                        .header("X-Actor-Id", "same-guy").header("X-Approval-Role", "QUALITY")
362	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA1\"}")),
363	                () -> callStatus(post("/api/batches/" + batchKey + "/approvals")
364	                        .header("X-Actor-Id", "same-guy").header("X-Approval-Role", "OPERATIONS")
365	                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA2\"}"))
366	        );
367	
368	        int ok = 0;
369	        int conflict = 0;
370	        for (Future<Integer> f : results) {
371	            int code = f.get(30, TimeUnit.SECONDS);
372	            if (code == 201) {
373	                ok++;
374	            } else if (code == 409) {
375	                conflict++;
376	            } else {
377	                fail("意外状态码: " + code);
378	            }
379	        }
380	        assertEquals(1, ok);
381	        assertEquals(1, conflict);
382	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey), "同一人不能完成两角色，批次不得 RELEASED");
383	    }
