```java
public StoredResponse load(String palletKey, LoadRequest req) {
    List<LoadRequest.LoadItem> items = req.items();
    List<String> keys = items.stream().map(LoadRequest.LoadItem::batchKey).toList();
    if (new HashSet<>(keys).size() != keys.size()) {
        throw ApiException.unprocessable("装载请求内 batchKey 重复");
    }
    List<String> parts = new ArrayList<>();
    parts.add("load"); parts.add(palletKey);
    for (var item : items) { parts.add(item.batchKey()); parts.add(item.category().trim()); parts.add(String.valueOf(item.compartmentNo())); }
    String fingerprint = IdempotentExecutor.fingerprint(parts.toArray(new String[0]));
    return idempotent.execute(CMD_LOAD, req.commandKey(), fingerprint, () -> {
        PalletRepository.PalletRow pallet = palletRepo.findPalletForUpdate(palletKey)
                .orElseThrow(() -> ApiException.notFound("托盘不存在: " + palletKey));
        if (!PalletStatus.OPEN.name().equals(pallet.status())) {
            throw ApiException.conflict("托盘状态 " + pallet.status() + " 不允许装载，仅 OPEN 可装载");
        }
        // 请求内分隔位-类别一致性
        Map<Integer, String> requestCompartmentCategory = new HashMap<>();
        for (var item : items) {
            String category = item.category().trim();
            String existing = requestCompartmentCategory.putIfAbsent(item.compartmentNo(), category);
            if (existing != null && !existing.equals(category)) {
                throw ApiException.unprocessable("分隔位 " + item.compartmentNo() + " 在请求内被多个类别占用: " + existing + " / " + category);
            }
        }
        List<LoadRow> current = palletRepo.findCurrentLoads(palletKey);
        Map<Integer, String> compartmentCategory = new HashMap<>();
        for (LoadRow row : current) compartmentCategory.put(row.compartmentNo(), row.category());
        for (var item : items) {
            String category = item.category().trim();
            String existing = compartmentCategory.get(item.compartmentNo());
            if (existing != null && !existing.equals(category)) {
                throw ApiException.unprocessable("分隔位 " + item.compartmentNo() + " 已装载类别 " + existing + "，与批次 " + item.batchKey() + " 类别 " + category + " 冲突");
            }
            compartmentCategory.putIfAbsent(item.compartmentNo(), category);
        }
        // 隔板充足性：可用分隔位 = 隔板数 + 1，须覆盖最大分隔位编号与类别数
        Set<String> categories = new HashSet<>();
        int maxCompartment = 0;
        for (LoadRow row : current) { categories.add(row.category()); maxCompartment = Math.max(maxCompartment, row.compartmentNo()); }
        for (var item : items) { categories.add(item.category().trim()); maxCompartment = Math.max(maxCompartment, item.compartmentNo()); }
        int required = Math.max(maxCompartment, categories.size()) - 1;
        if (pallet.dividerCount() < required) {
            throw ApiException.unprocessable("隔板数量不足: 实际 " + pallet.dividerCount() + "，要求 " + required + "，差额 " + (required - pallet.dividerCount()));
        }
        // 批次状态校验（按业务键排序加锁，与召回/检验等按提交顺序串行）
        List<String> sortedKeys = new ArrayList<>(new HashSet<>(keys));
        Collections.sort(sortedKeys);
        Map<String, BatchRepository.BatchRow> batches = new HashMap<>();
        for (String key : sortedKeys) {
            BatchRepository.BatchRow batch = batchRepo.findBatchForUpdate(key)
                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + key));
            batches.put(key, batch);
        }
        for (var item : items) {
            BatchRepository.BatchRow batch = batches.get(item.batchKey());
            String status = batch.status();
            if (!LOADABLE_STATUSES.contains(status)) {
                throw ApiException.unprocessable("批次 " + item.batchKey() + " 状态 " + status + " 不允许装载，须未召回且未放行");
            }
            assertNoRecalledAncestor(item.batchKey());  // need lineage — via batchRepo
            palletRepo.findOccupancy(item.batchKey()).ifPresent(o -> {
                throw ApiException.unprocessable("批次 " + item.batchKey() + " 已被托盘 " + o.palletKey() + " 占用");
            });
        }
        String now = now();
        List<PalletLoadEntry> entries = new ArrayList<>(items.size());
        for (int i = 0; i < items.size(); i++) {
            var item = items.get(i);
            String category = item.category().trim();
            long loadId = palletRepo.insertLoad(new LoadRow(0L, palletKey, item.batchKey(), category, item.compartmentNo(), i + 1, PalletLoadStatus.LOADED.name(), false, null, req.commandKey(), now, null));
            palletRepo.insertOccupancy(new OccupancyRow(item.batchKey(), palletKey, loadId, now));
            entries.add(new PalletLoadEntry(item.batchKey(), category, item.compartmentNo(), i + 1, PalletLoadStatus.LOADED, false, null, Instant.parse(now), null));
        }
        LoadResponse body = new LoadResponse(palletKey, pallet.dividerVersion(), entries, Instant.parse(now));
        return new StoredResponse(201, toJson(body));
    });
}
```

